(r/'app.js').write_text(r'''"use strict";
const $=s=>document.querySelector(s);let mode='vuln',page='home',session=null;
const modules=[['home','실습 개요','전체 항목 살펴보기'],['orders','주문 조회 · SQLi','객체 권한과 검색 쿼리 비교'],['roles','관리자 권한','클라이언트 역할값 변조'],['notes','게시판 · XSS','저장형·반사형 HTML 처리'],['profile','프로필 · CSRF','변경 요청의 토큰 검사'],['uploads','파일 업로드','HTML 업로드와 다운로드 권한'],['javascript','JS · 정보 노출','엔드포인트와 가짜 키 분석']];
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}
function escape(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function api(path,options={}){const method=options.method||'GET';let headers={...options.headers};if(session&&mode==='fixed'&&method!=='GET')headers['X-CSRF-Token']=session.csrf;$('#httpMethod').textContent=method;$('#httpPath').textContent=path;try{const res=await fetch(path,{...options,headers});const text=await res.text();let data;try{data=JSON.parse(text)}catch{data=text}$('#response').textContent=`HTTP ${res.status} ${res.statusText}\n\n`+(typeof data==='string'?data:JSON.stringify(data,null,2));if(!res.ok)throw Error(data.error||`HTTP ${res.status}`);return data}catch(e){toast(e.message);throw e}}
function post(path,data){return api(path,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(data)})}
function path(s){return '/api/'+mode+'/'+s}
function loginUI(){const u=session?.user;$('#who').textContent=u?`${u.USERNAME} · ${u.ROLE}`:'로그인 전';$('#logout').hidden=!u;$('#loginBox').hidden=!!u;$('#state').textContent=u?'실습 진행 중':'로그인 필요'}
function nav(){const n=$('#nav');n.replaceChildren();modules.forEach(([id,title],i)=>{let b=document.createElement('button');b.className=id===page?'active':'';b.innerHTML=`<b>${String(i+1).padStart(2,'0')}</b>${title}`;b.onclick=()=>{page=id;render().catch(()=>{})};n.append(b)})}
async function render(){nav();loginUI();$('#chapter').textContent=String(modules.findIndex(x=>x[0]===page)+1).padStart(2,'0')+' / '+modules.find(x=>x[0]===page)[1];let w=$('#workspace');
if(page==='home'){w.innerHTML='<h2>진단할 기능을 선택하세요</h2><p class="desc">기능을 조작해 정상 요청을 만든 다음, Burp Repeater에서 값을 변경해 비교합니다.</p><div class="cards"></div><div class="hint">계정: alice / bob / admin<br>공통 비밀번호: LabOnly!2026<br>비교 모드를 바꾸면 경로가 바뀝니다. 게시글·업로드 자료는 모드별로 분리됩니다.</div>';modules.slice(1).forEach(([id,t,d],i)=>{let b=document.createElement('button');b.className='card';b.innerHTML=`<span class="num">LAB ${String(i+1).padStart(2,'0')}</span><h3>${t}</h3><small>${d}</small>`;b.onclick=()=>{page=id;render().catch(()=>{})};w.querySelector('.cards').append(b)});return}
if(!session){w.innerHTML='<h2>먼저 실습 계정에 로그인하세요</h2><p class="desc">위의 계정 선택에서 alice로 시작한 뒤, 필요할 때 로그아웃하고 bob 또는 admin으로 전환하세요.</p>';return}
if(page==='orders'){w.innerHTML=`<h2>내 주문과 검색 결과</h2><p class="desc">내 주문 조회는 사용자별로 제한됩니다. 주문 상세와 검색에서 각각 권한 검사와 SQL 파라미터화를 비교합니다. 검색 목록은 공용 상품 카탈로그입니다.</p><table><thead><tr><th>주문 번호</th><th>상품</th><th>금액</th><th></th></tr></thead><tbody id="orders"></tbody></table><div class="row"><input id="oid" value="102" aria-label="주문 번호"><button id="detail" class="primary">상세 요청</button></div><div class="row"><input id="query" placeholder="상품 검색어" aria-label="상품 검색어"><button id="search" class="primary">검색 요청</button></div><div class="hint">alice의 주문: 101, 103 · bob의 주문: 102<br>상세 요청의 ID를 바꿔 소유권 검사를 확인하세요. 검색어에 작은따옴표를 입력해 SQL 오류 처리도 비교할 수 있습니다.</div>`;$('#detail').onclick=()=>api(path('orders/'+encodeURIComponent($('#oid').value))).catch(()=>{});$('#search').onclick=()=>api(path('search')+'?q='+encodeURIComponent($('#query').value)).catch(()=>{});const rows=await api(path('orders'));$('#orders').innerHTML=rows.map(x=>`<tr><td>${x.ID}</td><td>${escape(x.PRODUCT)}</td><td>${x.AMOUNT.toLocaleString()}원</td><td><button data-id="${x.ID}">상세</button></td></tr>`).join('');$('#orders').querySelectorAll('button').forEach(b=>b.onclick=()=>api(path('orders/'+b.dataset.id)).catch(()=>{}));}
if(page==='roles'){w.innerHTML=`<h2>관리자 사용자 목록</h2><p class="desc">일반 사용자의 요청에 role=ADMIN을 넣었을 때, 서버가 실제 세션 권한을 확인하는지 비교합니다.</p><div class="row"><select id="role"><option>USER</option><option>ADMIN</option></select><button class="primary" id="admin">사용자 목록 요청</button></div><code class="endpoint">${path('admin/users')}?role=ADMIN</code><div class="hint">취약 경로는 전달받은 role 값을 신뢰합니다.<br>수정 경로는 DB에서 로그인 사용자의 실제 역할을 조회합니다.</div>`;$('#admin').onclick=()=>api(path('admin/users')+'?role='+$('#role').value).catch(()=>{});}
if(page==='notes'){w.innerHTML=`<h2>업무 메모 게시판</h2><p class="desc">메모는 DB에 저장됩니다. 취약 화면은 저장된 본문을 HTML로 출력하고, 수정 화면은 텍스트로 출력합니다.</p><textarea id="note" aria-label="업무 메모" placeholder="메모를 입력하세요. HTML 처리 비교도 가능합니다."></textarea><div class="row"><button id="saveNote" class="primary">메모 저장</button><button id="preview">별도 창에서 미리보기 ↗</button></div><div id="notes"></div><div class="hint">비교 예: &lt;b&gt;보안 점검&lt;/b&gt;<br>모드별 메모가 별도로 저장됩니다. 반사형 미리보기는 /vuln/preview와 /fixed/preview에서 비교합니다.</div>`;$('#saveNote').onclick=async()=>{try{await post(path('notes'),{body:$('#note').value});await render()}catch{}};$('#preview').onclick=()=>window.open('/'+mode+'/preview?text='+encodeURIComponent($('#note').value),'_blank','noopener');const rows=await api(path('notes'));for(const x of rows){let d=document.createElement('div');d.className='note';d.innerHTML=`<small>사용자 ${x.OWNER_ID} · ${escape(x.ID.slice(0,8))}</small><div class="body"></div>`;if(mode==='vuln')d.querySelector('.body').innerHTML=x.BODY;else d.querySelector('.body').textContent=x.BODY;$('#notes').append(d)}}
if(page==='profile'){w.innerHTML=`<h2>연락처 변경</h2><p class="desc">세션 쿠키만으로 상태 변경을 허용하는지 확인합니다. 수정 모드의 정상 UI는 CSRF 토큰을 자동으로 전송합니다.</p><div class="row"><input id="email" value="${escape(session.user.EMAIL)}" aria-label="이메일"><button id="update" class="primary">이메일 변경</button></div><div class="hint">Burp Repeater에서 X-CSRF-Token 헤더를 제거한 뒤 재전송하세요.<br>취약 경로는 성공하고 수정 경로는 403을 반환합니다.<br>실제 교차 사이트 요청 성립 여부는 브라우저의 SameSite 쿠키 정책에도 영향을 받습니다.</div>`;$('#update').onclick=async()=>{try{session.user=await post(path('profile'),{email:$('#email').value});loginUI()}catch{}};}
if(page==='uploads'){w.innerHTML=`<h2>첨부파일 업로드</h2><p class="desc">취약 모드는 HTML을 포함한 임의 파일을 저장하고 공개 URL에서 inline으로 제공합니다. 수정 모드는 실제 PNG/JPEG를 확인하고 소유자에게 첨부 다운로드로 제공합니다.</p><div class="row"><input id="file" type="file" aria-label="첨부파일"><button id="upload" class="primary">업로드</button></div><div id="files"></div><div class="hint">최대 1 MiB · 파일 내용은 DB BLOB으로 저장됩니다.<br>실습 샘플: fixtures/demo.html, fixtures/pixel.png<br>bob으로 바꿔 alice의 수정 모드 파일 URL에 접근해 보세요.</div>`;$('#upload').onclick=async()=>{const f=$('#file').files[0];if(!f)return toast('파일을 선택하세요');try{await api(path('uploads')+'?name='+encodeURIComponent(f.name),{method:'POST',headers:{'Content-Type':f.type||'application/octet-stream'},body:f});await render()}catch{}};const rows=await api(path('uploads'));for(const x of rows){let a=document.createElement('a');a.className='filelink';a.href='/'+mode+'/uploads/'+x.ID;a.target='_blank';a.rel='noopener';a.textContent=x.FILENAME+' ↗';$('#files').append(a)}}
if(page==='javascript'){w.innerHTML=`<h2>JavaScript 분석 · 정보 노출</h2><p class="desc">별도 JS 파일을 불러와 HTTP history 기반 분석을 시험합니다. 샘플 키는 모두 실습용 가짜 값입니다.</p><div class="row"><button id="loadJS" class="primary">${mode==='vuln'?'가짜 키가 있는 JS':'정보를 제거한 JS'} 불러오기</button><button id="config">설정 API 요청</button></div><code class="endpoint">/assets/${mode==='vuln'?'lab-endpoints.js':'safe-endpoints.js'}</code><div class="hint">Burp의 Proxy history를 켜고 JS 분석 결과에서 URL·키 후보를 확인하세요. 실제 서비스 키·토큰은 포함하지 않았습니다.<br>/v3/api-docs, /nginx_status는 환경 탐지·경로 확인에 사용할 수 있습니다.</div>`;$('#loadJS').onclick=async()=>{try{await api('/assets/'+(mode==='vuln'?'lab-endpoints.js':'safe-endpoints.js'));toast('JS 응답을 HTTP history에 추가했습니다.')}catch{}};$('#config').onclick=()=>api(path('config')).catch(()=>{});}
}
$('#loginForm').onsubmit=async e=>{e.preventDefault();try{session=await post('/api/auth/login',{username:$('#username').value,password:$('#password').value});await render();toast('로그인했습니다.')}catch{}};
$('#logout').onclick=async()=>{try{await api('/api/auth/logout',{method:'POST',headers:{'X-CSRF-Token':session.csrf}});session=null;render().catch(()=>{})}catch{}};
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));$('.mode').classList.toggle('fixed',mode==='fixed');$('#modeDesc').textContent=mode==='vuln'?'의도적으로 취약한 경로를 사용합니다.':'검증·권한 검사·안전한 출력이 적용됩니다.';$('#modeBadge').textContent='/api/'+mode;render().catch(()=>{})});
$('#clear').onclick=()=>{$('#response').textContent='응답 본문이 여기에 표시됩니다.';$('#httpMethod').textContent='READY';$('#httpPath').textContent='다음 요청 대기 중'};
(async()=>{try{const h=await fetch('/health').then(r=>r.json());$('#dbName').textContent=h.database;$('#dbHint').textContent=h.status==='UP'?'DB 연결 정상':'DB 확인 필요'}catch{$('#dbName').textContent='연결 확인 실패'}try{const r=await fetch('/api/auth/me');if(r.ok)session=await r.json()}catch{}await render()})().catch(()=>{});
''',encoding='utf-8')
